/** Penalty formula: N lakh = N×₹100/day → rate = loanAmount / 1000 */ function calcPenalty(dueDate, loanAmount) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const due = new Date(dueDate);
    due.setHours(0, 0, 0, 0);
    const daysOverdue = Math.max(0, Math.floor((today.getTime() - due.getTime()) / 86400000));
    const ratePerDay = Math.round(loanAmount / 1000);
    return {
        daysOverdue,
        ratePerDay,
        auto: daysOverdue * ratePerDay
    };
}
